def bgm(ct: Literal[str], wt: str, w, m, c, it: int, lb: float, ss, dof):
    b = BayesianGaussianMixture(n_components=4, covariance_type=ct, weight_concentration_prior_type=wt, random_state=0, max_iter=300).fit(X)
    tag = "bgm_" + ct + "_" + wt
    close(tag + "_w", b.weights_, w, 1e-5, 1e-7); close(tag + "_m", b.means_, m, 1e-5)
    close(tag + "_c", b.covariances_, c, 1e-5)
    if b.n_iter_ != it:
        print("TEST FAILED", tag, "n_iter", b.n_iter_, it)
    closes(tag + "_lb", b.lower_bound_, lb); close(tag + "_ss", b.score_samples(X[:4]), ss, 1e-5)
    close(tag + "_dof", b.degrees_of_freedom_, dof, 1e-6)

